<?php
require __DIR__.'/includes/bootstrap.php'; require_login(); require __DIR__.'/includes/layout.php'; require __DIR__.'/includes/records.php';
$kind=selected_kind();$def=definitions()[$kind];$rows=filtered_records($kind);
$search=is_string($_GET['q']??null)?$_GET['q']:'';$year=is_string($_GET['year']??null)?$_GET['year']:'';
$years=db()->query('SELECT DISTINCT YEAR(event_date) y FROM incidents ORDER BY y DESC')->fetchAll();
page_header($def['title'],$kind); ?>
<div class="section-heading"><p>Tambah, periksa, dan perbarui catatan bencana.</p><a class="button" href="form.php?kind=<?=e($kind)?>">+ Tambah <?=e($def['singular'])?></a></div><section class="panel"><form method="get" class="toolbar"><input type="hidden" name="kind" value="<?=e($kind)?>"><label class="search">Cari data<input name="q" value="<?=e($search)?>" placeholder="Nama, lokasi, atau status…"></label><label>Tahun kejadian<select name="year"><option value="">Semua tahun</option><?php foreach($years as $y): ?><option value="<?=e($y['y'])?>" <?=$year===(string)$y['y']?'selected':''?>><?=e($y['y'])?></option><?php endforeach; ?></select></label><button>Terapkan</button><a class="button secondary" href="data.php?kind=<?=e($kind)?>">Reset</a><a class="button secondary" href="export.php?<?=e(http_build_query(['kind'=>$kind,'q'=>$search,'year'=>$year]))?>">Ekspor CSV ↓</a></form><p class="small"><?=count($rows)?> catatan ditemukan. Ekspor mengikuti filter aktif.</p><div class="table-wrap"><table><thead><tr>
<?php $columns=$kind==='incidents'?['Nama / lokasi','Tanggal','Jenis','Status','Meninggal / luka / hilang','Aksi']:($kind==='people'?['Nama / usia','Kejadian','Status','Lokasi terakhir','Posko','Aksi']:['Nama posko','Kejadian','Lokasi','Penghuni / kapasitas','Kebutuhan','Aksi']); foreach($columns as $c): ?><th><?=e($c)?></th><?php endforeach; ?></tr></thead><tbody><?php foreach($rows as $r): ?><tr>
<?php if($kind==='incidents'): ?><td><b><?=e($r['name'])?></b><small><?=e($r['location'].', '.$r['district'].', '.$r['province'])?></small></td><td><?=e($r['event_date'])?></td><td><?=e($r['type'])?></td><td><span class="badge"><?=e($r['status'])?></span></td><td><?=e($r['deaths'].' / '.$r['injured'].' / '.$r['missing'])?></td>
<?php elseif($kind==='people'): ?><td><b><?=e($r['name'])?></b><small><?=e($r['age'])?> tahun</small></td><td><?=e($r['incident_name'])?></td><td><span class="badge"><?=e($r['status'])?></span></td><td><?=e($r['last_location'])?></td><td><?=e($r['shelter_name']??'Tidak terhubung')?></td>
<?php else: ?><td><b><?=e($r['name'])?></b></td><td><?=e($r['incident_name'])?></td><td><?=e($r['location'])?></td><td><?=e($r['occupancy'].' / '.$r['capacity'])?><progress max="<?=max(1,(int)$r['capacity'])?>" value="<?=(int)$r['occupancy']?>"><?=e($r['occupancy'])?></progress></td><td><?=e($r['needs'])?></td><?php endif; ?>
<td><div class="actions"><a href="form.php?kind=<?=e($kind)?>&amp;id=<?=(int)$r['id']?>">Detail / ubah</a><a class="danger-text" href="delete.php?kind=<?=e($kind)?>&amp;id=<?=(int)$r['id']?>">Hapus</a></div></td></tr><?php endforeach; ?></tbody></table></div><?php if(!$rows): ?><div class="empty"><h3>Tidak ada catatan</h3><p>Tambahkan data pertama atau ubah kata kunci pencarian.</p></div><?php endif; ?><p class="small">Data individu dan rekap kejadian dikelola terpisah. Jumlah penghuni posko diperbarui manual. Gunakan identitas minimum yang diperlukan untuk pendataan.</p></section><?php page_footer(); ?>
